template <typename Char> class float_writer {
 private:
  float_format_state<Char> state_;

 public:
  explicit float_writer(const basic_format_specs<Char>& specs,
                        const float_specs& fspecs)
      : state_{specs, fspecs} {}

  template <typename OutputIt>
  OutputIt write_nonfinite(OutputIt out, bool isinf) {
    float_format_state<Char>& state = state_;
    basic_format_specs<Char>& specs = state.specs;
    const float_specs& fspecs = state.fspecs;
    auto str = nonfinite_name(isinf, fspecs.upper);
    constexpr size_t str_size = 3;
    auto sign = fspecs.sign;
    auto size = str_size + (sign ? 1 : 0);
    unsigned spec_width = to_unsigned(specs.width);
    size_t padding = spec_width > size ? spec_width - size : 0;
    auto* shifts = data::left_padding_shifts;
    size_t left_padding = padding >> shifts[specs.align];
    size_t right_padding = padding - left_padding;
    const fill_t<Char>& fill = specs.fill;
    size_t fill_size = fill.size();
    const Char* fill_data = fill.data();
    auto it = reserve(out, size + padding * fill_size);
    if (left_padding != 0) {
      if (fill_size == 1)
        it = detail::fill_n(it, left_padding, fill_data[0]);
      else {
        for (size_t i = 0; i < left_padding; ++i)
          it = copy_str<Char>(fill_data, fill_data + fill_size, it);
      }
    }
    if (sign) *it++ = static_cast<Char>(data::signs[sign]);
    it = copy_str<Char>(str, str + str_size, it);
    if (right_padding != 0) {
      if (fill_size == 1)
        it = detail::fill_n(it, right_padding, fill_data[0]);
      else {
        for (size_t i = 0; i < right_padding; ++i)
          it = copy_str<Char>(fill_data, fill_data + fill_size, it);
      }
    }
    return base_iterator(out, it);
  }
};

